def even_bit_set_number(n):
    # Convert the number to binary and remove the '0b' prefix
    bin_n = bin(n)[2:]

    # Initialize an empty string to store the binary number with even bits set
    even_bin_n = ''

    # Iterate over the binary number from right to left (least significant bit to most)
    for i in range(len(bin_n)):
        # If the bit is even (i.e., the position is even), set it to 1
        if i % 2 == 0:
            even_bin_n = '1' + even_bin_n
        # If the bit is odd, keep it the same
        else:
            even_bin_n = bin_n[i] + even_bin_n

    # Convert the binary string back to an integer and return it
    return int(bin(int(even_bin_n, 2)), 2)

